// referencePath is the reference documentation of ymcp's external
// interfaces, generated by TestReference.
const referencePath = "../../docs/reference.md"

// TestReference checks that docs/reference.md describes ymcp as the code
// defines it: the command line, the MCP tools and prompts with their
// inputs and outputs, the tools a pipeline's agent gets, and the pipeline
// file. YMCP_REFERENCE=write rewrites it.
func TestReference(t *testing.T) {
	got := reference(t)
	if os.Getenv("YMCP_REFERENCE") == "write" {
		if err := os.WriteFile(referencePath, []byte(got), 0o644); err != nil {
			t.Fatal(err)
		}
		return
	}
	want, err := os.ReadFile(referencePath)
	if err != nil {
		t.Fatal(err)
	}
	if string(want) != got {
		t.Fatal("docs/reference.md is out of date; run YMCP_REFERENCE=write go test ./cmd/ymcp -run TestReference")
	}
}

func reference(t *testing.T) string {
	t.Helper()
	var b strings.Builder
	b.WriteString(`# ymcp reference

<!-- Generated by TestReference in cmd/ymcp/reference_test.go; don't edit by hand. -->

ymcp has four external interfaces, each described here from the code that defines it:

- [the command line](#command-line);
- [the MCP server](#mcp-server): its tools and prompts, over stdio or Streamable HTTP;
- [the pipeline tools](#pipeline-tools) a pipeline's agent gets;
- [the pipeline file](#pipeline-file) that configures a pipeline.

The [README](../README.md) explains how they fit together.

## Command line

Every command reads its profiles from the configuration file (see [Configuration](../README.md#configuration)) and
takes ` + "`--profile <key>`" + ` (or ` + "`YMCP_PROFILE`" + `). Output goes to standard output; an error goes to
standard error, and the command exits with status 1.

`)
	for _, u := range []string{usage, pipelineUsage, pipelineNotifyUsage} {
		b.WriteString("```text\n" + strings.TrimRight(u, "\n") + "\n```\n\n")
	}

	served, prompts := listTools(t)
	b.WriteString(`## MCP server

` + "`ymcp serve`" + ` speaks the Model Context Protocol over stdio, or Streamable HTTP with ` + "`--transport http`" + `
(see [HTTP](../README.md#http)). It offers the tools and prompts below; a profile may serve only some groups of them
(see [Choosing tools](../README.md#choosing-tools)).

**Output.** A tool answers with one text content: indented JSON for data, short text for a confirmation. Attachments
may come as images or resources. A failure is a result with ` + "`isError: true`" + ` and a message that says what
went wrong and what to do: the allowed values, the tool that finds the right ID, or the permission that is missing.
Custom fields go in and come out by their display names.

**Confirmation.** With confirmations on (a profile's default; ` + "`serve --confirm off`" + ` turns them off), every tool
marked destructive below takes one more optional argument, ` + "`confirm`" + ` (string). ` + "`apply_command`" + ` asks only for
commands that remove something, ` + "`call_api`" + ` only for DELETE. Called without ` + "`confirm`" + `, the tool changes
nothing and answers ` + "`{\"confirmationRequired\": true, \"operationId\", \"operation\", \"confirm\", \"expiresAt\", \"message\"}`" + `;
the model asks the user, and if they agree calls again with the same arguments and ` + "`confirm`" + ` set to that
secret. A secret works once, for those arguments, for 10 minutes.

`)
	for _, g := range tools.Groups {
		fmt.Fprintf(&b, "### %s\n\n", g.Title)
		for _, name := range g.Tools {
			tl, ok := served[name]
			if !ok {
				t.Fatalf("%s is grouped but not served", name)
			}
			writeTool(&b, tl)
		}
	}
	b.WriteString("### Prompts\n\n")
	for _, p := range prompts {
		fmt.Fprintf(&b, "#### `%s`\n\n%s\n\n", p.Name, oneParagraph(p.Description))
		if len(p.Arguments) > 0 {
			b.WriteString("| Argument | Required | Description |\n|---|---|---|\n")
			for _, a := range p.Arguments {
				fmt.Fprintf(&b, "| `%s` | %s | %s |\n", a.Name, yesNo(a.Required), cell(a.Description))
			}
			b.WriteString("\n")
		}
	}

	b.WriteString(`## Pipeline tools

A pipeline gives its agent the MCP tools above, under the name ` + "`ymcp`" + `, and these three, which talk to the
pipeline running it.

`)
	for _, tl := range pipelineTools(t) {
		writeTool(&b, tl)
	}

	b.WriteString(`## Pipeline file

A pipeline is a JSON file in ` + "`<config dir>/ymcp/pipelines/<name>.json`" + `, written by the wizard or by hand
(see [Pipelines](../README.md#pipelines)). These are its fields; durations are strings such as ` + "`\"90s\"`" + `,
` + "`\"10m\"`" + ` or ` + "`\"2h\"`" + `, and templates take ` + "`{{issue.id}}`" + `-style keys.

| Field | Type | Description |
|---|---|---|
`)
	for _, f := range pipelineFields(t) {
		fmt.Fprintf(&b, "| `%s` | %s | %s |\n", strings.ReplaceAll(f.path, "|", `\|`), f.typ, cell(f.doc))
	}
	return strings.TrimRight(b.String(), "\n") + "\n"
}

// writeTool describes a tool: what it does, its hints and its input.
func writeTool(b *strings.Builder, tl *mcp.Tool) {
	fmt.Fprintf(b, "#### `%s`\n\n", tl.Name)
	if a := tl.Annotations; a != nil {
		var hints []string
		switch {
		case a.ReadOnlyHint:
			hints = append(hints, "read-only")
		case a.DestructiveHint != nil && *a.DestructiveHint:
			hints = append(hints, "destructive")
		default:
			hints = append(hints, "changes data")
		}
		if a.IdempotentHint && !a.ReadOnlyHint {
			hints = append(hints, "idempotent")
		}
		title := tl.Title
		if title == "" {
			title = a.Title
		}
		fmt.Fprintf(b, "*%s* · %s\n\n", title, strings.Join(hints, ", "))
	}
	b.WriteString(oneParagraph(tl.Description) + "\n\n")
	params := schemaParams(tl.InputSchema)
	if len(params) == 0 {
		b.WriteString("No input.\n\n")
		return
	}
	b.WriteString("| Input | Type | Required | Description |\n|---|---|---|---|\n")
	for _, p := range params {
		fmt.Fprintf(b, "| `%s` | %s | %s | %s |\n", p.name, p.typ, yesNo(p.required), cell(p.doc))
	}
	b.WriteString("\n")
}

type param struct {
	name, typ, doc string
	required       bool
}

// schemaParams are the top-level properties of a tool's input schema.
func schemaParams(schema any) []param {
	raw, _ := json.Marshal(schema)
	var s struct {
		Properties map[string]json.RawMessage `json:"properties"`
		Required   []string                   `json:"required"`
	}
	if json.Unmarshal(raw, &s) != nil {
		return nil
	}
	var out []param
	for name, p := range s.Properties {
		var prop struct {
			Description string `json:"description"`
		}
		_ = json.Unmarshal(p, &prop)
		out = append(out, param{name: name, typ: schemaType(p), doc: prop.Description, required: slices.Contains(s.Required, name)})
	}
	sort.Slice(out, func(i, j int) bool {
		if out[i].required != out[j].required {
			return out[i].required
		}
		return out[i].name < out[j].name
	})
	return out
}

// schemaType names a JSON schema's type: "string", "array of string",
// "object", "string or null".
func schemaType(raw json.RawMessage) string {
	var s struct {
		Type  json.RawMessage `json:"type"`
		Items json.RawMessage `json:"items"`
		Enum  []any           `json:"enum"`
	}
	if json.Unmarshal(raw, &s) != nil {
		return "any"
	}
	var types []string
	var one string
	if json.Unmarshal(s.Type, &one) == nil && one != "" {
		types = []string{one}
	} else {
		_ = json.Unmarshal(s.Type, &types)
	}
	for i, ty := range types {
		if ty == "array" && len(s.Items) > 0 {
			types[i] = "array of " + schemaType(s.Items)
		}
	}
	if len(types) == 0 {
		return "any"
	}
	out := strings.Join(types, " or ")
	if len(s.Enum) > 0 {
		var vals []string
		for _, v := range s.Enum {
			vals = append(vals, fmt.Sprintf("`%v`", v))
		}
		out += ": " + strings.Join(vals, ", ")
	}
	return out
}

// listTools lists the tools and prompts a server with every tool offers.
func listTools(t *testing.T) (map[string]*mcp.Tool, []*mcp.Prompt) {
	t.Helper()
	yt, err := youtrack.New(youtrack.Options{BaseURL: "https://yt.example.com", Login: "a", Password: "b", Proxy: "none"})
	if err != nil {
		t.Fatal(err)
	}
	server := mcp.NewServer(&mcp.Implementation{Name: "reference", Version: "0"}, nil)
	tools.Register(server, yt, nil)
	ct, st := mcp.NewInMemoryTransports()
	ctx := context.Background()
	if _, err := server.Connect(ctx, st, nil); err != nil {
		t.Fatal(err)
	}
	cs, err := mcp.NewClient(&mcp.Implementation{Name: "reference"}, nil).Connect(ctx, ct, nil)
	if err != nil {
		t.Fatal(err)
	}
	defer cs.Close()
	tl, err := cs.ListTools(ctx, nil)
	if err != nil {
		t.Fatal(err)
	}
	byName := map[string]*mcp.Tool{}
	for _, x := range tl.Tools {
		byName[x.Name] = x
	}
	pl, err := cs.ListPrompts(ctx, nil)
	if err != nil {
		t.Fatal(err)
	}
	return byName, pl.Prompts
}

// noCallbacks are pipeline callbacks for listing the tools only.
type noCallbacks struct{}

func (noCallbacks) RequestInput(context.Context, int64, string) error      { return nil }
func (noCallbacks) Report(context.Context, int64, string) error            { return nil }
func (noCallbacks) SetChange(context.Context, int64, string, string) error { return nil }

// pipelineTools are the tools of a pipeline's MCP server that aren't
// YouTrack tools.
func pipelineTools(t *testing.T) []*mcp.Tool {
	t.Helper()
	yt, err := youtrack.New(youtrack.Options{BaseURL: "https://yt.example.com", Login: "a", Password: "b", Proxy: "none"})
	if err != nil {
		t.Fatal(err)
	}
	s := mcpserver.New(yt, "ref", map[string]bool{"get_issue": true}, nil, noCallbacks{}, nil)
	base, err := s.Start("127.0.0.1:0")
	if err != nil {
		t.Fatal(err)
	}
	t.Cleanup(func() { s.Close() })
	token := s.Grant(mcpserver.RunInfo{ID: 1, Number: 1, Pipeline: "ref"})
	ctx := context.Background()
	cs, err := mcp.NewClient(&mcp.Implementation{Name: "reference"}, nil).Connect(ctx, &mcp.StreamableClientTransport{
		Endpoint:   base + "/ref",
		HTTPClient: &http.Client{Transport: bearerToken(token)},
		MaxRetries: -1,
	}, nil)
	if err != nil {
		t.Fatal(err)
	}
	defer cs.Close()
	tl, err := cs.ListTools(ctx, nil)
	if err != nil {
		t.Fatal(err)
	}
	var out []*mcp.Tool
	for _, x := range tl.Tools {
		if x.Name != "get_issue" {
			out = append(out, x)
		}
	}
	sort.Slice(out, func(i, j int) bool { return out[i].Name < out[j].Name })
	if len(out) == 0 {
		t.Fatal("the pipeline server lists no pipeline tools")
	}
	return out
}

// bearerToken adds a bearer token to every request.
type bearerToken string

func (b bearerToken) RoundTrip(r *http.Request) (*http.Response, error) {
	r = r.Clone(r.Context())
	r.Header.Set("Authorization", "Bearer "+string(b))
	return http.DefaultTransport.RoundTrip(r)
}

type field struct{ path, typ, doc string }

// pipelineFields are the fields of the pipeline file, read from the
// declarations and comments of the spec package.
func pipelineFields(t *testing.T) []field {
	t.Helper()
	dir := filepath.Join("..", "..", "internal", "pipeline", "spec")
	fset := token.NewFileSet()
	paths, err := filepath.Glob(filepath.Join(dir, "*.go"))
	if err != nil {
		t.Fatal(err)
	}
	structs := map[string]*ast.StructType{}
	for _, path := range paths {
		if strings.HasSuffix(path, "_test.go") {
			continue
		}
		f, err := parser.ParseFile(fset, path, nil, parser.ParseComments)
		if err != nil {
			t.Fatal(err)
		}
		for _, d := range f.Decls {
			gd, ok := d.(*ast.GenDecl)
			if !ok {
				continue
			}
			for _, sp := range gd.Specs {
				ts, ok := sp.(*ast.TypeSpec)
				if !ok {
					continue
				}
				if st, ok := ts.Type.(*ast.StructType); ok {
					structs[ts.Name.Name] = st
				}
			}
		}
	}
	delete(structs, "Duration") // a string in JSON
	var out []field
	var walk func(prefix string, st *ast.StructType)
	walk = func(prefix string, st *ast.StructType) {
		// Fields that are all of one struct type, such as the stages, are
		// described once: stages.<working|review|…>.enter.
		if names, inner := sameStruct(st, structs); inner != nil {
			walk(prefix+"<"+strings.Join(names, "|")+">.", inner)
			return
		}
		for _, fl := range st.Fields.List {
			name := jsonName(fl)
			if name == "" {
				continue
			}
			path := prefix + name
			doc := strings.TrimSpace(commentText(fl.Doc) + " " + commentText(fl.Comment))
			if rest, ok := strings.CutPrefix(doc, fl.Names[0].Name+" "); ok && rest != "" { // Go's "AutoCompact compacts …"
				doc = rest
			}
			if doc != "" {
				doc = strings.ToUpper(doc[:1]) + doc[1:]
			}
			typ, inner := goType(fl.Type, structs)
			out = append(out, field{path, typ, doc})
			if inner != nil && typ == "object" {
				walk(path+".", inner)
			}
		}
	}
	root, ok := structs["Pipeline"]
	if !ok {
		t.Fatal("no Pipeline struct in the spec package")
	}
	walk("", root)
	return out
}

// jsonName is a field's name in JSON, or "" for one JSON leaves out.
func jsonName(fl *ast.Field) string {
	if len(fl.Names) == 0 || fl.Tag == nil {
		return ""
	}
	name, _, _ := strings.Cut(reflectTag(strings.Trim(fl.Tag.Value, "`"), "json"), ",")
	if name == "-" {
		return ""
	}
	return name
}

// sameStruct reports the JSON names of a struct's fields when they are all
// of one struct type, and that type.
func sameStruct(st *ast.StructType, structs map[string]*ast.StructType) ([]string, *ast.StructType) {
	var names []string
	var typ string
	for _, fl := range st.Fields.List {
		id, ok := fl.Type.(*ast.Ident)
		name := jsonName(fl)
		if !ok || name == "" || structs[id.Name] == nil || (typ != "" && id.Name != typ) {
			return nil, nil
		}
		typ = id.Name
		names = append(names, name)
	}
	if len(names) < 2 {
		return nil, nil
	}
	return names, structs[typ]
}

// goType names a field's JSON type, and the struct it holds, if any.
func goType(e ast.Expr, structs map[string]*ast.StructType) (string, *ast.StructType) {
	switch e := e.(type) {
	case *ast.StarExpr:
		return goType(e.X, structs)
	case *ast.Ident:
		switch e.Name {
		case "string":
			return "string", nil
		case "bool":
			return "boolean", nil
		case "int", "int64":
			return "number", nil
		case "Duration":
			return "duration", nil
		}
		if st, ok := structs[e.Name]; ok {
			return "object", st
		}
		return e.Name, nil
	case *ast.ArrayType:
		inner, _ := goType(e.Elt, structs)
		return "array of " + inner, nil
	case *ast.MapType:
		inner, _ := goType(e.Value, structs)
		return "object of " + inner, nil
	}
	return "any", nil
}

// reflectTag reads one key of a struct tag.
func reflectTag(tag, key string) string {
	for tag != "" {
		tag = strings.TrimLeft(tag, " ")
		k, rest, ok := strings.Cut(tag, ":\"")
		if !ok {
			return ""
		}
		v, rest, _ := strings.Cut(rest, "\"")
		if k == key {
			return v
		}
		tag = rest
	}
	return ""
}

func commentText(g *ast.CommentGroup) string {
	if g == nil {
		return ""
	}
	return strings.Join(strings.Fields(g.Text()), " ")
}

// oneParagraph joins a description's lines.
func oneParagraph(s string) string { return strings.Join(strings.Fields(s), " ") }

// cell escapes text for a table cell.
func cell(s string) string {
	return strings.ReplaceAll(oneParagraph(s), "|", `\|`)
}

func yesNo(b bool) string {
	if b {
		return "yes"
	}
	return "no"
}
